import{_ as a,C as n,o as s,c as r,j as e,a as d,E as c,ag as l}from"./chunks/framework.HG0H2VLS.js";const f=JSON.parse('{"title":"UpdateScreen","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/update-screen.md","filePath":"cc-templates/update-screen.md"}'),i={name:"cc-templates/update-screen.md"};function u(p,t,h,b,g,m){const o=n("ComponentDemo");return s(),r("div",null,[t[0]||(t[0]=e("hr",null,null,-1)),t[1]||(t[1]=e("h2",{id:"title-updatescreen",tabindex:"-1"},[d("title: UpdateScreen "),e("a",{class:"header-anchor",href:"#title-updatescreen","aria-label":'Permalink to "title: UpdateScreen"'},"​")],-1)),t[2]||(t[2]=e("h1",{id:"updatescreen",tabindex:"-1"},[d("UpdateScreen "),e("a",{class:"header-anchor",href:"#updatescreen","aria-label":'Permalink to "UpdateScreen"'},"​")],-1)),t[3]||(t[3]=e("blockquote",null,[e("p",null,[e("code",null,"/control/update"),d(" on v3, composed from Alert, RecordSection, FieldRow, Button, Badge, Select and Modal on the ControlScreen shell")])],-1)),c(o,{src:"/demos/src/cc/templates/UpdateScreen/UpdateScreen.html"}),t[4]||(t[4]=l('<h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>From</th><th>Notes</th></tr></thead><tbody><tr><td>Shell</td><td>ControlScreen (cloned from ControlHub.html)</td><td>Breadcrumb Zone Selector › System › Update; header title only, no actions</td></tr><tr><td>Warning</td><td>Alert <code>--warning</code> (<code>--fixed</code> in full width)</td><td>Merges classic&#39;s two texts: run when usage is low, plus how long updates take</td></tr><tr><td>Result banner</td><td>Alert <code>--success</code> / <code>--danger</code></td><td>&quot;&lt;update type&gt; successful / failed&quot;, classic&#39;s own wording (<code>sUpdateType</code>)</td></tr><tr><td>Groups</td><td>RecordSection (<code>--full</code> in full width)</td><td>Classic&#39;s two blank &quot;delimiter&quot; rows become two sections. <strong>Titles &quot;Updates&quot; / &quot;Maintenance&quot; are proposals.</strong> Classic has none</td></tr><tr><td>Rows</td><td>FieldRow <code>--paragraph</code> + a third <code>&lt;dd class=&quot;cc-update__run&quot;&gt;</code></td><td>Label = action, value = classic description (+ extras), trailing Button</td></tr><tr><td>Actions</td><td>Button <code>--secondary --sm</code></td><td>&quot;Open&quot; + external-link (new tab) for Release Notes / Updater; &quot;Run&quot; for the rest</td></tr><tr><td>Counts</td><td>Badge <code>--sm --neutral</code></td><td>Skins count, Guest / Bot cache counts, CDN version</td></tr><tr><td>Zone</td><td>Select <code>sel__control--sm</code>, <code>size-2</code> wide</td><td>Clear Cache only. Sits <strong>inline beside Run</strong> with no visible label (<code>aria-label=&quot;Zone to clear&quot;</code>), Flowbite-style (designer, 2026-10-02; was stacked under the text with a &quot;Zone&quot; label). Re-counts the badges</td></tr><tr><td>Confirm</td><td>Modal <code>--sm</code></td><td>System, Re-Initialize, Clear Cache, CDN Files, Reset Scheduled Tasks</td></tr></tbody></table><h2 id="running-state-designer-2026-10-02" tabindex="-1">Running state (designer, 2026-10-02) <a class="header-anchor" href="#running-state-designer-2026-10-02" aria-label="Permalink to &quot;Running state (designer, 2026-10-02)&quot;">​</a></h2><p>While an action runs, its row shows a status block under the description, and every other Run button is disabled so two updates can&#39;t overlap.</p><table tabindex="0"><thead><tr><th>Actions</th><th>Shows</th><th>Cancel</th></tr></thead><tbody><tr><td>Update All Skins, Update Internal Links (<code>data-update-total</code>)</td><td>Spinner <code>--sm --brand</code> + &quot;Updating skins… 34 of 128&quot; + progress bar</td><td>Yes: Run becomes <strong>Cancel</strong></td></tr><tr><td>The other eight</td><td>Spinner + &quot;Running…&quot;</td><td>No: each is a single server step, with nothing to stop part-way</td></tr></tbody></table><ul><li><strong>Progress bar:</strong> RoomCard&#39;s Figma-built bar, token for token (<code>spacing-2</code> tall, <code>radius-full</code>, <code>surface-contrast</code> track, <code>surface-brand</code> fill). The fill eases with <code>--ao-transition-default</code>, and doesn&#39;t under reduced motion.</li><li><strong>Outcome banners:</strong> success &quot;… successful · 128 of 128 skins updated.&quot;; cancel (Alert <code>--warning</code>) &quot;… cancelled · 34 of 128 skins updated.&quot;; failure (Alert <code>--danger</code>) &quot;… failed · 384 of 640 links updated before it stopped.&quot;</li><li><strong>a11y:</strong> the status block is <code>role=&quot;status&quot;</code>, the row gets <code>aria-busy</code>, the Cancel button is labelled &quot;Cancel Update All Skins&quot;, and focus returns to the button when the job ends.</li></ul><h2 id="rows-classic-order-and-copy" tabindex="-1">Rows (classic order and copy) <a class="header-anchor" href="#rows-classic-order-and-copy" aria-label="Permalink to &quot;Rows (classic order and copy)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key (<code>uKey</code>)</th><th>Label</th><th>SSC</th><th>Kind</th><th>Confirm</th></tr></thead><tbody><tr><td>releasenotes</td><td>Release Notes</td><td>2</td><td>open (new tab)</td><td>—</td></tr><tr><td>updater</td><td>Affino Updater</td><td>2</td><td>open (new tab)</td><td>—</td></tr><tr><td>system</td><td>System</td><td>1</td><td>run</td><td>✓</td></tr><tr><td>designelements</td><td>Design Elements</td><td>1</td><td>run</td><td>—</td></tr><tr><td>skins</td><td>Update All Skins</td><td>1</td><td>popup</td><td>—</td></tr><tr><td>ReInitialize</td><td>Re-Initialize</td><td>1</td><td>run</td><td>✓</td></tr><tr><td>ClearGuestCache</td><td>Clear Cache</td><td>1</td><td>popup</td><td>✓</td></tr><tr><td>cdn</td><td>CDN Files</td><td>1</td><td>run</td><td>✓</td></tr><tr><td>RegionsAndCities</td><td>Regions and Cities</td><td>1</td><td>run</td><td>—</td></tr><tr><td>ResetScheduledTasks</td><td>Reset Scheduled Tasks</td><td>1</td><td>run</td><td>✓</td></tr><tr><td>UpdateInternalLinks</td><td>Update Internal Links</td><td>1</td><td>popup</td><td>—</td></tr><tr><td>UpdateAIPrompts</td><td>Update AI Prompts</td><td>1</td><td>run</td><td>—</td></tr></tbody></table><p>Classic also adds <strong>Update Zone Skins</strong> when reached with <code>?Action=UpdateZoneSkins&amp;ZoneCode=n</code>, and auto-opens the skins popup for <code>Action=UpdateAllSkins</code> / <code>UpdateZoneSkins</code>. Both are kept for the backend (see Backend), but not drawn.</p><h2 id="layout-values-all-borrowed-no-new-tokens" tabindex="-1">Layout values (all borrowed, no new tokens) <a class="header-anchor" href="#layout-values-all-borrowed-no-new-tokens" aria-label="Permalink to &quot;Layout values (all borrowed, no new tokens)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>Borrowed from</th></tr></thead><tbody><tr><td>Page gap</td><td><code>spacing-5</code> (0 in full width)</td><td>RecordScreen card gap</td></tr><tr><td>Row value column gap</td><td><code>spacing-3</code></td><td>FieldRow stacked label → value gap</td></tr><tr><td>Count badges gap</td><td><code>spacing-2</code></td><td><code>.field-row__tags</code></td></tr><tr><td>Zone select width</td><td><code>size-2</code> (160px)</td><td>—</td></tr><tr><td>Action column gap (select ↔ Run)</td><td><code>spacing-3</code></td><td>the value column&#39;s gap</td></tr><tr><td>Card border / shadow</td><td><code>border/card</code>, <code>shadow/2xs</code> (standard only)</td><td>The CC top-level card rule</td></tr></tbody></table><h2 id="backend-todo-backend-updatescreen-manifest-update-actions" tabindex="-1">Backend (<code>TODO(backend:UpdateScreen)</code>, manifest <code>update-actions</code>) <a class="header-anchor" href="#backend-todo-backend-updatescreen-manifest-update-actions" aria-label="Permalink to &quot;Backend (`TODO(backend:UpdateScreen)`, manifest `update-actions`)&quot;">​</a></h2><ul><li>Run → <code>GET {thisDoc}?uKey=&lt;key&gt;&amp;update=1</code>; the server renders the result banner.</li><li>Popups stay dialogs: <code>DC_UpdateSkins.cfm?clearcache=1[&amp;ZoneCode=]</code>, <code>ClearGuestCache.cfm?ZoneCode=</code>, <code>UpdateInternalLinksPopup.cfm</code>.</li><li>Rows render only when the user&#39;s SSC list contains <code>data-ssc</code>.</li><li>Counts are live: skins assigned to channels, <code>PageCache</code> Guest / Bot, <code>Site.CDNVersion</code>. The zone re-count goes via <code>PageCache.cfc?method=GetClearCacheCount&amp;zonecode=</code> → <code>{GUESTCOUNT, BOTCOUNT}</code>.</li><li>CDN bumps <code>Site.CDNVersion</code>, then reloads with <code>?clearcache=1</code>.</li><li><strong>Flag:</strong> classic&#39;s inline <code>uKey=ClearGuestCache</code> branch runs <code>DELETE FROM PageCache</code> with no zone filter, while the popup path takes the zone. Keep the zone-aware path.</li><li>Confirmation before the five destructive actions is <strong>new behaviour</strong> and needs Luismi&#39;s agreement.</li><li><strong>Progress + cancel is new and needs two endpoints:</strong> a status feed for the long jobs (skins, internal links), e.g. <code>GET …/status?job=&lt;id&gt;</code> → <code>{done, total, state}</code>, polled; and <code>POST …/cancel?job=&lt;id&gt;</code>, which stops after the current item and reports <code>done</code>. Classic runs these in Boxy popups, so v3 shows the progress inline instead.</li></ul><h2 id="demo-switches" tabindex="-1">Demo switches <a class="header-anchor" href="#demo-switches" aria-label="Permalink to &quot;Demo switches&quot;">​</a></h2><p><code>?fail=&lt;key&gt;</code> previews a failure for that action (progressive ones stop at about 60%). <code>?ssc=1</code> previews a user without SSC 2 (hides Release Notes / Updater).</p>',15))])}const k=a(i,[["render",u]]);export{f as __pageData,k as default};
